contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        string calldata name_,
        string calldata symbol_,
        uint256 maintenance_,
        uint256 fundingFee_,
        uint256 makerFee_,
        uint256 takerFee_,
        uint256 positionFee_,
        uint256 makerLimit_,
        int256 minRate_,
        int256 maxRate_,
        int256 targetRate_,
        uint256 targetUtilization_,
        uint256 badFee_
    ) public {
        require(makerFee_ <= 1e18, "makerFee too large");
        require(takerFee_ <= 1e18, "takerFee too large");
        require(positionFee_ <= 1e18, "positionFee too large");
        require(fundingFee_ <= 1e18, "fundingFee too large");

        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(minRate_)),
            maxRate: PackedFixed18.wrap(int128(maxRate_)),
            targetRate: PackedFixed18.wrap(int128(targetRate_)),
            targetUtilization: PackedUFixed18.wrap(uint128(targetUtilization_))
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name_,
            symbol: symbol_,
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(0),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(c)),
            maintenance: UFixed18.wrap(maintenance_),
            fundingFee: UFixed18.wrap(fundingFee_),
            makerFee: UFixed18.wrap(makerFee_),
            takerFee: UFixed18.wrap(takerFee_),
            positionFee: UFixed18.wrap(positionFee_),
            makerLimit: UFixed18.wrap(makerLimit_),
            utilizationCurve: curve
        });

        c.initialize(info);

        bool reverted;
        try c.updateTakerFee(UFixed18.wrap(badFee_)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        string memory storedName = c.name();
        string memory storedSymbol = c.symbol();
        uint256 storedMaintenance = UFixed18.unwrap(c.maintenance());
        uint256 storedFundingFee = UFixed18.unwrap(c.fundingFee());
        uint256 storedMakerFee = UFixed18.unwrap(c.makerFee());
        uint256 storedTakerFee = UFixed18.unwrap(c.takerFee());
        uint256 storedPositionFee = UFixed18.unwrap(c.positionFee());
        uint256 storedMakerLimit = UFixed18.unwrap(c.makerLimit());

        assert(
            keccak256(bytes(storedName)) == keccak256(bytes(name_)) &&
            keccak256(bytes(storedSymbol)) == keccak256(bytes(symbol_)) &&
            storedMaintenance == maintenance_ &&
            storedFundingFee == fundingFee_ &&
            storedMakerFee == makerFee_ &&
            storedMakerLimit == makerLimit_ &&
            storedPositionFee == positionFee_ &&
            storedTakerFee == takerFee_ &&
            storedTakerFee <= 1e18 &&
            (reverted || badFee_ == takerFee_)
        );
    }

    receive() external payable {}
}

