contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 rateRaw, uint256 targetUtilization) public {
        require(rateRaw <= uint256(uint128(type(int128).max)), "rate too large");
        require(targetUtilization <= uint256(type(uint128).max), "util too large");
        require(rateRaw <= 1e30, "rate too large");

        PackedFixed18 rate = PackedFixed18.wrap(int128(uint128(rateRaw)));
        JumpRateUtilizationCurve memory curve = JumpRateUtilizationCurve({
            minRate: rate,
            maxRate: rate,
            targetRate: rate,
            targetUtilization: PackedUFixed18.wrap(uint128(targetUtilization))
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "T",
            symbol: "T",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(0),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(c)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: curve
        });

        c.initialize(info);

        JumpRateUtilizationCurve memory stored = c.utilizationCurve();

        assert(
            PackedFixed18.unwrap(stored.minRate) == PackedFixed18.unwrap(rate) &&
            PackedFixed18.unwrap(stored.targetRate) == PackedFixed18.unwrap(rate) &&
            PackedFixed18.unwrap(stored.maxRate) == PackedFixed18.unwrap(rate) &&
            PackedUFixed18.unwrap(stored.targetUtilization) == uint128(targetUtilization)
        );
    }

    receive() external payable {}
