contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(amount < 1e24);

        // fresh product must be at version 0
        require(c.latestVersion() == 0);

        bool reverted;
        try c.openTake(UFixed18.wrap(amount)) { reverted = false; } catch { reverted = true; }

        // uninitialized product: position changes must fail and version stays 0
        assert(reverted && c.latestVersion() == 0);
    }
    receive() external payable {}
}

